const rgRe=d=>new RegExp('(^|[^A-Za-z0-9₀-₉])('+Object.keys(d).sort((a,b)=>b.length-a.length).map(s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')(?![A-Za-z0-9₀-₉])','g');
;

