function figKeys(f){
const out=[];
f.querySelectorAll('figure.mol[data-k], .op, .arw i').forEach(e=>{
if(e.matches('figure.mol'))out.push(e.dataset.k);
else{const t=e.textContent;out.push(...rgKeys(t,RG3RE,RG3));if(e.matches('.arw i'))out.push(...rgKeys(t,RG3WRE,RG3W))}});
const q=f.closest('.card')?.querySelector('.q');if(q)out.push(...rgKeys(q.textContent,RG3RE,RG3));
return [...new Set(out)]}
;

