/* 3D del laboratorio: sustratos, los 4 nucleófilos/bases de la ronda, disolventes y, tras reaccionar, lo que pasó */
const SNREAG={'HO⁻':'hidroxido','CH₃O⁻':'metoxido','H₂O':'agua','CH₃OH':'metanol','I⁻':'yoduro','CN⁻':'cianuro','t-BuO⁻':'tbuoxido'};
;

const SNPROD={hidroxido:['propanol','propan2ol','tbuoh'],agua:['propanol','propan2ol','tbuoh'],metoxido:['metoxipropano1','metoxipropano2','mtbe'],metanol:['metoxipropano1','metoxipropano2','mtbe'],yoduro:['yodopropano1','yodopropano2','tbui'],cianuro:['butanonitrilo','metilpropanonitrilo','dimetilpropanonitrilo']};
;

function sn3Open(s,done){
const subs=['bromopropano1','bromopropano2','tbubr'],sub=subs[s.sub-1],
nus={s:SNREAG[s.sg],b:'tbuoxido',n:SNREAG[s.gn],w:SNREAG[s.wk]},nu=nus[s.nu],
pro=s.nu==='w'?nu:'etanol',sv=s.sv==='p'?pro:'dmso',
G=[{t:T('⚡ Electrófilos (sustrato)','⚡ Electrophiles (substrate)'),ks:subs,cur:[sub]},
{t:T('💪 Nucleófilos / bases','💪 Nucleophiles / bases'),ks:[nus.s,nus.b,nus.n,nus.w],cur:[nu]},
{t:T('💧 Disolventes','💧 Solvents'),ks:[pro,'dmso'],cur:[sv]}];
if(done){const o=snf(s),ks=[];
if(o==='SN1'||o==='E1')ks.push(s.sub===3?'tbucat':'ipcat');            /* carbocatión intermedio */
if(o==='E2')ks.push('nw_e2p'+s.sub);                                    /* H y Br anti-periplanares */
if(o==='SN1'||o==='SN2'||o==='mix')ks.push(SNPROD[nu][s.sub-1]);
if(o==='E1'||o==='E2')ks.push(s.sub===3?'metilpropeno':'propeno');
if(o!=='none')ks.push('bromuro');
if(ks.length)G.push({t:T('🎯 Resultado','🎯 Result'),ks,cur:[]})}
open3DK([sub,...G.flatMap(g=>g.ks)],G)}
;

function open3DK(keys,groups){
keys=keys.filter(k=>M3[k]);
if(!keys.length)return;
const o=LS.get('v3',{s:'bs',h:true}),st={k:keys[0],s:V3S[o.s]?o.s:'bs',h:o.h!==false,spin:!RM};
const m=document.createElement('div');m.className='modal m3d';
m.innerHTML=`<div class="card v3" role="dialog" aria-modal="true" aria-labelledby="v3t"><div class="v3hd"><h2 id="v3t"></h2><button class="v3close" id="v3c" type="button" aria-label="${_t('close')}">✕</button></div>
<div class="v3box" id="v3b" tabindex="0" aria-label="${_t('v3area')}"><div class="v3msg" id="v3m">${_t('v3load')}</div></div>
<div class="v3ctl">${groups?groups.map(g=>`<div class="chips mols" role="group" aria-label="${esc(g.t)}"><span class="gl">${esc(g.t)}</span>${g.ks.map(k=>`<button class="chipb" data-mk="${k}">${(g.cur||[]).includes(k)?'★ ':''}${esc(m3n(k))}</button>`).join('')}</div>`).join(''):keys.length>1?`<div class="chips mols" role="group" aria-label="${_t('v3mol')}">${keys.map(k=>`<button class="chipb" data-mk="${k}">${esc(m3n(k))}</button>`).join('')}</div>`:''}
<div class="chips" role="group" aria-label="${_t('v3view')}">${['bs','st','sp'].map(s=>`<button class="chipb" data-ms="${s}">${_t('v3'+s)}</button>`).join('')}<button class="chipb" data-mt="h">${_t('v3h')}</button><button class="chipb" data-mt="spin">${_t('v3spin')}</button><button class="chipb" id="v3r">↺ ${_t('v3reset')}</button></div>
<p class="hint">${_t('v3hint')}</p></div><div class="acts"><button class="go alt" id="v3x">${_t('close')}</button></div></div>`;
document.body.appendChild(m);
const x=m.querySelector('#v3c');x.focus();x.onclick=close3D;m.querySelector('#v3x').onclick=close3D;m.onclick=e=>{if(e.target===m)close3D()};document.addEventListener('keydown',esc3D);
const sync=()=>{m.querySelector('#v3t').textContent=m3n(st.k);
m.querySelectorAll('[data-mk]').forEach(b=>{b.classList.toggle('on',b.dataset.mk===st.k);b.setAttribute('aria-pressed',b.dataset.mk===st.k)});
m.querySelectorAll('[data-ms]').forEach(b=>{b.classList.toggle('on',b.dataset.ms===st.s);b.setAttribute('aria-pressed',b.dataset.ms===st.s)});
m.querySelectorAll('[data-mt]').forEach(b=>{const v=!!st[b.dataset.mt];b.classList.toggle('on',v);b.setAttribute('aria-pressed',v)})};
const draw=(fit)=>{if(!V3)return;V3.setStyle({},V3S[st.s]);if(!st.h)V3.setStyle({elem:'H'},{});
if(fit){V3.zoomTo();V3.zoom(1.45)}V3.spin(st.spin?'y':false,.5);V3.render()};
const FIX=/^(nw_|silla|bote)/;  /* conformaciones: la vista inicial es la que enseña (Newman, silla de perfil) */
const reset=()=>{const v=V3.getView();v[4]=0;v[5]=0;v[6]=0;v[7]=1;V3.setView(v)};
const load=()=>{if(!V3)return;if(FIX.test(st.k))st.spin=false;sync();V3.removeAllModels();V3.addModel(sdf(st.k),'sdf');reset();draw(true)};
m.querySelectorAll('[data-mk]').forEach(b=>b.onclick=()=>{st.k=b.dataset.mk;sync();load()});
m.querySelectorAll('[data-ms]').forEach(b=>b.onclick=()=>{st.s=b.dataset.ms;LS.set('v3',{s:st.s,h:st.h});sync();draw()});
m.querySelectorAll('[data-mt]').forEach(b=>b.onclick=()=>{st[b.dataset.mt]=!st[b.dataset.mt];if(b.dataset.mt==='h')LS.set('v3',{s:st.s,h:st.h});sync();draw()});
m.querySelector('#v3r').onclick=()=>{if(!V3)return;st.spin=false;sync();reset();draw(true)};
/* el giro automático se detiene en cuanto la persona toca o arrastra el modelo, para que pueda moverlo ella */
const box=m.querySelector('#v3b'),stopSpin=()=>{if(st.spin&&V3){st.spin=false;V3.spin(false);sync()}};
box.addEventListener('pointerdown',e=>{stopSpin()},{capture:true});
box.addEventListener('wheel',stopSpin,{capture:true,passive:true});
/* teclado: flechas giran, + y - acercan */
box.addEventListener('keydown',e=>{if(e.target!==box||!V3)return;const k={ArrowLeft:['y',-1],ArrowRight:['y',1],ArrowUp:['x',-1],ArrowDown:['x',1]}[e.key];
if(k){e.preventDefault();stopSpin();V3.rotate(k[1]*12,k[0]);V3.render()}else if(e.key==='+'||e.key==='='||e.key==='-'){e.preventDefault();stopSpin();V3.zoom(e.key==='-'?1/1.12:1.12);V3.render()}});
sync();
lib3D().then(()=>{if(!m.isConnected)return;
V3=$3Dmol.createViewer(m.querySelector('#v3b'),{backgroundColor:'white',backgroundAlpha:0,antialias:true});
load();m.querySelector('#v3m').remove()}).catch(()=>{const t=m.querySelector('#v3m');if(t)t.textContent=_t('v3fail')})}
;

function burst(el,n,power){
if(RM||!el)return;n=n||16;power=power||1;
const r=el.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,cols=['#FF5C7A','#FFE45C','#5EE0B5','#A99CFF'];
for(let i=0;i<n;i++){
const p=document.createElement('i');p.className='cf';const s=7+Math.random()*7;
p.style.cssText=`left:${cx}px;top:${cy}px;width:${s}px;height:${s}px;background:${cols[i%4]};border-radius:${Math.random()<.5?'50%':'2px'}`;
document.body.appendChild(p);
const a=Math.random()*Math.PI*2,d=(70+Math.random()*100)*power;
p.animate([{transform:'translate(-50%,-50%) scale(1)',opacity:1},{transform:`translate(calc(-50% + ${Math.cos(a)*d}px),calc(-50% + ${Math.sin(a)*d-50}px)) rotate(${Math.random()*540}deg) scale(.5)`,opacity:0}],{duration:650+Math.random()*450,easing:'cubic-bezier(.15,.8,.3,1)'}).onfinish=()=>p.remove()}}
;

function upd(id,html,hot){
const e=document.getElementById(id);if(!e)return;
if(hot!==undefined)e.classList.toggle('hot',hot);
if(e.innerHTML===html)return;
e.innerHTML=html;e.classList.remove('bump');void e.offsetWidth;e.classList.add('bump')}
;

const hearts=()=>[0,1,2].map(i=>`<span class="hr${i>=S.lives?' off':''}"><svg width="22" height="22" viewBox="0 0 24 24" fill="${i>=S.lives?'none':'currentColor'}" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round" aria-hidden="true"><path d="M12 20s-7-4.4-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 10c0 5.6-7 10-7 10z"/></svg></span>`).join('');
;

const stk=()=>`<span class="lbl">${_t('streak')}</span><span class="fl" style="--s:${S.streak}">${FLM}</span><b>x${S.streak}</b>`;
;

const pulse=e=>{e.classList.remove('bump');void e.offsetWidth;e.classList.add('bump')};
;

function hudUpd(ok,gain){
const lv=document.getElementById('p-lv');
if(lv){lv.innerHTML=hearts();lv.setAttribute('aria-label',_t('ariaLives',S.lives));if(!ok){const h=lv.children[S.lives];if(h)h.classList.add('brk')}}
const sc=document.getElementById('p-sc');
if(sc){sc.textContent=''+S.score;pulse(sc);
if(ok&&gain&&!RM){const f=document.createElement('i');f.className='gain';f.textContent='+'+gain;sc.parentNode.appendChild(f);setTimeout(()=>f.remove(),900)}}
const st=document.getElementById('p-st');
if(st){st.innerHTML=stk();st.classList.toggle('hot',S.streak>=3);st.classList.toggle('fire',S.streak>=5);pulse(st)}
const hb=document.querySelector('.hudbar');
if(!ok&&hb&&!RM){hb.classList.remove('shk');void hb.offsetWidth;hb.classList.add('shk')}}
;

function fx(ok){
const card=$.querySelector('.card');
if(ok)burst($.querySelector('.opt.good')||$.querySelector('.eq')||card,S.streak>=5?28:16,S.streak>=5?1.5:1)}
;

function countUp(el,to){
if(!el)return;if(RM||to===0){el.textContent=to+' pts';return}
const t0=performance.now(),D=900;
(function tick(t){const k=Math.min(1,(t-t0)/D),v=Math.round(to*(1-Math.pow(1-k,3)));el.textContent=v+' pts';if(k<1)requestAnimationFrame(tick)})(t0)}
;


