function rMol(it){
 const expected=atoms(it[0]),elements=Object.keys(expected),selected=Object.fromEntries(elements.map(sym=>[sym,0]));
 const name=it[1][LANG==='en'?1:0];
 $.innerHTML=hud()+`<div class="card"><p class="q">${T('Construye la fórmula de','Build the formula for')} <span class="tg">${name}</span></p><p class="dnh">${T('Usa + y − para elegir cuántos átomos de cada elemento lleva.','Use + and − to choose how many atoms of each element it contains.')}</p><div class="mol-builder" id="mol-builder">${elements.map(sym=>{const el=EL.find(x=>x[0]===sym);const elName=cap(el?el[1]:sym);return `<div class="mol-row"><span class="mol-el"><b>${sym}</b><small>${elName}</small></span><span class="mol-controls"><button type="button" data-atom="${sym}" data-delta="-1" aria-label="${T('Quitar un átomo de ','Remove one ')+elName}">−</button><output id="mol-${sym}">0</output><button type="button" data-atom="${sym}" data-delta="1" aria-label="${T('Añadir un átomo de ','Add one ')+elName}">+</button></span></div>`}).join('')}</div><p class="mol-preview" id="mol-preview" aria-live="polite"></p><button class="go" id="mol-check">${T('Comprobar fórmula','Check formula')}</button><div id="fb"></div></div>`;
 const preview=document.getElementById('mol-preview'),check=document.getElementById('mol-check');
 $.querySelectorAll('#mol-builder button').forEach(b=>b.onclick=()=>{const sym=b.dataset.atom;selected[sym]=Math.max(0,selected[sym]+Number(b.dataset.delta));document.getElementById('mol-'+sym).textContent=selected[sym];preview.innerHTML=sub(elements.map(el=>selected[el]?(el+(selected[el]>1?selected[el]:'')):'').join(''))});
 check.onclick=()=>{const ok=elements.every(sym=>selected[sym]===expected[sym]);S.cur={q:`${T('Fórmula de ','Formula for ')}${name}`,a:sub(it[0]),e:''};$.querySelectorAll('#mol-builder button').forEach(b=>b.disabled=true);check.disabled=true;verdict(ok,`${T('La fórmula correcta es ','The correct formula is ')}${sub(it[0])}.`)};
}
;

