{const X2={"aro": [["Which group strongly activates the benzene ring?", "–NH₂", ["–NO₂", "–CF₃", "–C≡N"], "The lone pair on N donates electron density to the ring."], ["What is benzene with one –CH₃ group called?", "Toluene", ["Phenol", "Aniline", "Styrene"], "Methylbenzene in systematic nomenclature."], ["Brominating benzene requires:", "Br₂ + FeBr₃", ["HNO₃ + H₂SO₄", "RCl + AlCl₃", "H₂ + Pt"], "FeBr₃ is the Lewis acid that activates Br₂."], ["How many π electrons does benzene have?", "6 (4n + 2, n = 1)", ["4 (4n, n = 1)", "8 (4n, n = 2)", "12 (4n, n = 3)"], "It follows Hückel’s rule, so it is aromatic."], ["Benzene + 1-chloropropane with AlCl₃ gives mostly isopropylbenzene because:", "The primary carbocation rearranges to a secondary one", ["The ring opens", "The meta isomer forms", "AlCl₃ is used up"], "A limitation of Friedel-Crafts alkylation."], ["Phenol is more acidic than an aliphatic alcohol because:", "Phenoxide is stabilized by resonance with the ring", ["The ring donates protons", "O is less electronegative", "It has more carbons"], "The negative charge is delocalized into the ring."]], "cet": [["LiAlH₄ reduces an aldehyde to:", "A primary alcohol", ["A secondary alcohol", "An acid", "An alkane"], "C=O becomes CH₂–OH."], ["A Grignard reagent + formaldehyde, then H₃O⁺, gives:", "A primary alcohol", ["A secondary alcohol", "A tertiary alcohol", "A ketone"], "Formaldehyde adds only one carbon, bearing two H."], ["A Grignard reagent + a ketone, then H₃O⁺, gives:", "A tertiary alcohol", ["A primary alcohol", "A secondary alcohol", "An aldehyde"], "The carbonyl carbon ends up with three carbon groups."], ["What is CH₃–CO–CH₃ called?", "Propanone (acetone)", ["Propanal", "Propan-2-ol", "Ethanone"], "The simplest ketone."], ["The Wittig reaction turns an aldehyde or ketone into:", "An alkene", ["An alcohol", "An imine", "An ester"], "It uses a phosphorus ylide."], ["An aldehyde is easily oxidized to:", "A carboxylic acid", ["A ketone", "An alcohol", "An alkane"], "That is why aldehydes are reducing agents."]], "ami": [["What is (CH₃)₂NH called?", "Dimethylamine", ["Trimethylamine", "Ethylamine", "Methanamide"], "A secondary amine with two methyl groups."], ["A secondary amine + an acid chloride forms:", "An N-substituted amide", ["An ester", "A diazonium salt", "An imine"], "Acylation of the amine."], ["Reducing a nitrile with LiAlH₄ gives:", "A primary amine", ["An aldehyde", "An amide", "An acid"], "C≡N becomes CH₂–NH₂."], ["Which is the strongest base?", "Dimethylamine", ["Aniline", "Pyridine", "Acetamide"], "Its lone pair is localized and available."], ["The Gabriel synthesis prepares:", "Primary amines", ["Tertiary amines", "Amides", "Diazonium salts"], "It avoids overalkylation."], ["An aryldiazonium ion + CuCl gives:", "An aryl chloride (Sandmeyer)", ["A phenol", "An aniline", "A nitrobenzene"], "N₂ is released as a gas."]], "aci": [["What is CH₃CO₂CH₂CH₃ called?", "Ethyl acetate (ethyl ethanoate)", ["Methyl ethanoate", "Ethanoic acid", "Ethanamide"], "The ester of acetic acid and ethanol."], ["An acid chloride + an alcohol gives:", "An ester", ["An amide", "An acetal", "An acid"], "Nucleophilic acyl substitution."], ["A carboxylic acid + SOCl₂ gives:", "An acid chloride", ["An anhydride", "An ester", "An amide"], "SO₂ and HCl are released."], ["An electron-withdrawing group near –CO₂H makes the acid:", "More acidic", ["Less acidic", "Equally acidic", "Basic"], "It stabilizes the carboxylate."], ["What is CH₃CONH₂ called?", "Acetamide (ethanamide)", ["Ammonium acetate", "Ethylamine", "Acetonitrile"], "The amide of acetic acid."], ["Acid hydrolysis of a nitrile gives:", "A carboxylic acid", ["An amine", "An aldehyde", "An alcohol"], "It goes through an amide intermediate."]]};for(const k in X2)ENX.org[k].push(...X2[k])}
;

Object.assign(ENX.org,{"alc": [["What is CH₃CH₂CH₂CH₂CH₃ called?", "Pentane", ["Butane", "Hexane", "Isopentane"], "Five carbons in a straight chain."], ["What is (CH₃)₂CHCH₂CH₃ called?", "2-methylbutane", ["Pentane", "3-methylbutane", "2,2-dimethylpropane"], "A four-carbon chain with a methyl on C2."], ["What is (CH₃)₄C called?", "2,2-dimethylpropane (neopentane)", ["2-methylbutane", "Pentane", "Butane"], "A three-carbon chain with two methyls on C2."], ["The general formula of an acyclic alkane is:", "CₙH₂ₙ₊₂", ["CₙH₂ₙ", "CₙH₂ₙ₋₂", "CₙHₙ"], "They are saturated: they hold the maximum number of hydrogens."], ["The general formula of a cycloalkane is:", "CₙH₂ₙ", ["CₙH₂ₙ₊₂", "CₙH₂ₙ₋₂", "CₙHₙ"], "The ring removes two hydrogens compared with the open-chain alkane."], ["In ethane, the most stable conformation is:", "Staggered", ["Eclipsed", "Gauche", "Chair"], "It has less torsional strain."], ["In butane, the most stable staggered conformation is:", "Anti", ["Gauche", "Totally eclipsed", "Partially eclipsed"], "The two methyl groups are as far apart as possible."], ["The most stable conformation of cyclohexane is:", "Chair", ["Boat", "Planar", "Eclipsed"], "It has no significant angle or torsional strain."], ["In a monosubstituted cyclohexane, the substituent prefers the position that is:", "Equatorial", ["Axial", "Both equally", "Neither"], "It avoids 1,3-diaxial interactions."], ["Complete combustion of an alkane produces:", "CO₂ and H₂O", ["CO and H₂", "C and H₂O", "CO₂ and H₂"], "A highly exothermic reaction."], ["Free-radical halogenation of an alkane needs:", "Light or heat", ["A Lewis acid", "A strong base", "A Pd catalyst"], "It starts the homolytic cleavage of the halogen."], ["In radical bromination, which hydrogen is replaced most selectively?", "Tertiary", ["Primary", "Methyl", "All equally"], "It forms the most stable radical."]], "hal": [["What is CH₃CH₂CH₂Br called?", "1-bromopropane", ["2-bromopropane", "1-bromoethane", "Ethyl bromide"], "Bromine on carbon 1 of a three-carbon chain."], ["What is (CH₃)₃CCl called?", "2-chloro-2-methylpropane (tert-butyl chloride)", ["1-chloro-2-methylpropane", "2-chlorobutane", "Isopropyl chloride"], "A tertiary halide."], ["The SN2 reaction happens:", "In one step, with inversion of configuration", ["In two steps, through a carbocation", "In one step, with retention", "In two steps, with racemization"], "The nucleophile attacks from the side opposite the leaving group."], ["The rate of an SN2 reaction depends on:", "The substrate and the nucleophile", ["Only the substrate", "Only the nucleophile", "Neither"], "It is bimolecular: second-order kinetics."], ["Which halide reacts fastest by SN2?", "Methyl bromide", ["tert-Butyl bromide", "Isopropyl bromide", "Neopentyl bromide"], "It has the least steric hindrance."], ["SN1 goes through:", "A carbocation intermediate", ["A single transition state", "A carbanion", "A radical"], "The slow step is the ionization of the substrate."], ["Which substrate favors SN1?", "A tertiary halide", ["A methyl halide", "A primary halide", "None"], "It forms the most stable carbocation."], ["A polar aprotic solvent (DMSO, acetone) favors:", "SN2", ["SN1", "E1", "Solvolysis"], "It does not solvate the nucleophile, which stays more reactive."], ["E2 requires:", "A strong base", ["A weak nucleophile and an acid", "UV light", "A transition metal"], "It is second order and concerted."], ["E1 (which competes with SN1) is favored by:", "A tertiary substrate, a weak base and heat", ["A methyl substrate and a strong base", "A primary substrate and DMSO", "A strong nucleophile at low temperature"], "It goes through the same carbocation as SN1; heat favors elimination."], ["In an E2, the H and the leaving group must be:", "Anti-coplanar", ["Syn", "Gauche", "Eclipsed at 60°"], "That lines up the orbitals that form the double bond."], ["According to Zaitsev’s rule, the main alkene is:", "The more substituted one", ["The less substituted one", "Always cis", "Always terminal"], "It is the most stable."], ["SN1 at a chiral carbon usually gives:", "A racemic mixture", ["Pure inversion", "Pure retention", "A meso compound"], "The nucleophile attacks the planar carbocation from both faces. In practice racemization is often partial, with a slight excess of the inverted product."]], "alq": [["What is CH₃CH=CHCH₃ called?", "But-2-ene", ["But-1-ene", "Butane", "2-methylpropene"], "The double bond starts at C2."], ["What is HC≡C–CH₂CH₃ called?", "But-1-yne", ["But-2-yne", "Butene", "Propyne"], "A four-carbon terminal alkyne."], ["HBr + propene (no peroxides) gives:", "2-bromopropane", ["1-bromopropane", "1,2-dibromopropane", "Propane"], "Markovnikov orientation."], ["Markovnikov’s rule: in HX + alkene, the H adds to the carbon that has:", "More hydrogens", ["Fewer hydrogens", "The leaving group", "The halogen"], "X ends up on the carbon that forms the more stable carbocation."], ["HBr with peroxides (ROOR) adds in a way that is:", "Anti-Markovnikov", ["Markovnikov", "Without orientation", "Syn"], "Radical mechanism; it only works with HBr."], ["Hydroboration-oxidation of a terminal alkene gives:", "A primary alcohol", ["A secondary alcohol", "A tertiary alcohol", "A diol"], "Anti-Markovnikov, syn addition."], ["Oxymercuration-demercuration of a terminal alkene gives:", "A secondary alcohol (Markovnikov)", ["A primary alcohol", "A diol", "An epoxide"], "No carbocation rearrangements."], ["Hydrogenating an alkene with H₂/Pt gives:", "An alkane (syn addition)", ["An alcohol", "A dihalide", "An epoxide"], "Both H atoms add to the same face."], ["Br₂ in CCl₄ with an alkene gives a vicinal dibromide by addition that is:", "Anti", ["Syn", "Radical", "Markovnikov"], "It goes through a bromonium ion."], ["Ozonolysis of an alkene (O₃, then Me₂S) gives:", "Aldehydes and/or ketones", ["Two alcohols", "An epoxide", "An alkane"], "It cleaves the C=C double bond."], ["An internal alkyne + Na in liquid NH₃ gives:", "A trans alkene", ["A cis alkene", "An alkane", "A ketone"], "Dissolving-metal reduction."], ["An alkyne + H₂ with Lindlar’s catalyst gives:", "A cis alkene", ["A trans alkene", "An alkane", "An aldehyde"], "The poisoned catalyst stops at the alkene."]], "est": [["A chiral carbon (stereocenter) has:", "Four different substituents", ["Two identical substituents", "A double bond", "A lone pair"], "This is the most common cause of chirality."], ["Enantiomers are:", "Non-superimposable mirror images", ["Constitutional isomers", "Superimposable on each other", "Conformations of the same compound"], "Like your left and right hands."], ["A 50:50 mixture of enantiomers is called:", "A racemic mixture", ["A meso compound", "A eutectic mixture", "A cis isomer"], "The rotations of the two enantiomers cancel out."], ["A racemic mixture has an optical rotation that is:", "Zero", ["Positive", "Negative", "Doubled"], "One enantiomer cancels the other."], ["A meso compound:", "Has stereocenters but is achiral", ["Has no stereocenters", "Is always optically active", "Is a racemic mixture"], "It has an internal plane of symmetry."], ["In the Cahn-Ingold-Prelog rules, priority is assigned by:", "Atomic number", ["Size of the group", "Number of carbons", "Boiling point"], "Higher atomic number means higher priority."], ["With the lowest-priority group in back, 1→2→3 going clockwise is:", "R", ["S", "E", "Z"], "Clockwise = R (rectus); counterclockwise = S."], ["What is the maximum number of stereoisomers for a molecule with 3 stereocenters?", "8", ["3", "6", "9"], "It is 2ⁿ, with n = 3."], ["A compound is optically active if:", "It is chiral and not racemic", ["It has a double bond", "It is achiral", "It has a plane of symmetry"], "Only then does it rotate polarized light."], ["Two enantiomers rotate polarized light:", "By the same amount in opposite directions", ["In the same direction", "One rotates it and the other does not", "Neither rotates it"], "That is why they are labeled d and l (or + and −)."], ["Which one is chiral: CHFClBr or CH₂ClBr?", "CHFClBr", ["CH₂ClBr", "Both", "Neither"], "CH₂ClBr has two identical H atoms."], ["An internal plane of symmetry means the molecule is:", "Achiral", ["Chiral", "Racemic", "Optically active"], "It is superimposable on its mirror image."]], "alo": [["What is CH₃CH₂CH₂OH called?", "Propan-1-ol", ["Propan-2-ol", "Propanal", "Ethanol"], "A three-carbon primary alcohol."], ["What is (CH₃)₂CHOH called?", "Propan-2-ol (isopropyl alcohol)", ["Propan-1-ol", "Propanone", "2-methylpropan-2-ol"], "A secondary alcohol."], ["A primary alcohol with PCC gives:", "An aldehyde", ["A carboxylic acid", "A ketone", "An ether"], "PCC stops the oxidation at the aldehyde."], ["A primary alcohol with a strong oxidant (Jones, CrO₃/H₂SO₄) gives:", "A carboxylic acid", ["An aldehyde", "A ketone", "An alkane"], "In water, the aldehyde keeps oxidizing."], ["A secondary alcohol with PCC gives:", "A ketone", ["An aldehyde", "An acid", "An ether"], "There is no extra H left to oxidize."], ["With Cr(VI) oxidants, tertiary alcohols:", "Are not easily oxidized", ["Give ketones", "Give aldehydes", "Give acids"], "The carbon bearing the OH has no hydrogen."], ["Dehydrating an alcohol with H₂SO₄ and heat gives:", "An alkene", ["An aldehyde", "An alkane", "A ketone"], "Water is lost and C=C forms."], ["An alcohol + SOCl₂ (with pyridine) gives:", "An alkyl chloride", ["An ester", "An aldehyde", "An alkene"], "It turns –OH into a good leaving group."], ["An alcohol + TsCl and pyridine forms:", "A tosylate (good leaving group)", ["An ether", "A ketone", "An acid halide"], "Tosylation keeps the carbon’s configuration; the SN2 that follows inverts it."], ["Which alcohol is the most acidic?", "Methanol", ["tert-Butanol", "Ethanol", "Propan-2-ol"], "Its alkoxide is less hindered and better solvated."], ["An alcohol + sodium metal forms:", "An alkoxide and hydrogen gas", ["An alkene", "An ether", "An aldehyde"], "An acid-base reaction that releases H₂."], ["With HBr by SN1, which alcohol reacts fastest?", "Tertiary", ["Primary", "Methanol", "All the same"], "It forms the most stable carbocation."]], "ete": [["What is CH₃CH₂OCH₂CH₃ called?", "Diethyl ether (ethoxyethane)", ["Dimethyl ether", "Ethanol", "Propanone"], "Two ethyl groups bonded to one O."], ["The Williamson synthesis uses:", "An alkoxide and an alkyl halide", ["Two alcohols and acid", "An aldehyde and an alcohol", "An alkene and a peroxide"], "It is an SN2 reaction."], ["In the Williamson synthesis, the halide should be:", "Primary", ["Tertiary", "Vinylic", "Aryl"], "Tertiary halides undergo elimination instead."], ["Cleaving an ether with HBr or HI gives:", "Alkyl halides", ["Aldehydes", "Alkenes", "Ketones"], "The C–O bond breaks by SN1 or SN2."], ["An epoxide forms when an alkene is treated with:", "A peroxyacid (MCPBA)", ["H₂/Pt", "Br₂/CCl₄", "NaBH₄"], "The O is transferred to the double bond."], ["An epoxide is an ether that is:", "A three-membered ring", ["A five-membered ring", "Open-chain", "Aromatic"], "It is also called an oxirane."], ["An epoxide opens easily because:", "It has ring strain", ["It is a strong acid", "It is aromatic", "It has a double bond"], "Opening the ring releases the strain."], ["With a strong nucleophile (basic conditions), the epoxide opens at the carbon that is:", "Less hindered", ["More substituted", "Neither", "Both equally"], "SN2 attack from the less crowded side."], ["Opening an epoxide with H₃O⁺ gives:", "A 1,2-diol (anti addition)", ["A 1,2-diol (syn addition)", "An ether", "An alkene"], "Water attacks from the face opposite the O."], ["THF and diethyl ether are used as solvents because:", "They are unreactive and solvate organometallics", ["They are strong acids", "They react with Grignard reagents", "They are protic"], "They stabilize Grignard reagents."], ["Ethers boil at lower temperatures than isomeric alcohols because:", "They do not hydrogen-bond with each other", ["They are heavier", "They are ionic", "They have more carbons"], "They have no O–H."], ["Crown ethers are used to:", "Solvate metal cations", ["Oxidize alcohols", "Reduce ketones", "Form epoxides"], "The ion fits inside the ring’s cavity."]]});
;

